// Start a new conversation.
func (c *internalClient) GenieStartConversation(ctx context.Context, req *GenieStartConversationRequest, opts ...call.Option) (*GenieStartConversationWaiter, error) {
	if req.SpaceId == nil {
		return nil, fmt.Errorf("request field %q required for polling is missing", "SpaceId")
	}
	capturedSpaceId := *req.SpaceId
	resp, err := c.genieStartConversationBase(ctx, req, opts...)
	if err != nil {
		return nil, err
	}
	if resp.MessageId == nil {
		return nil, fmt.Errorf("response field %q required for polling is missing", "MessageId")
	}
	if resp.ConversationId == nil {
		return nil, fmt.Errorf("response field %q required for polling is missing", "ConversationId")
	}
	return &GenieStartConversationWaiter{
		poll:           c.GenieGetConversationMessage,
		messageId:      *resp.MessageId,
		conversationId: *resp.ConversationId,
		spaceId:        capturedSpaceId,
	}, nil
}

// GenieStartConversationWaiter tracks the state of the operation started by GenieStartConversation.
type GenieStartConversationWaiter struct {
	poll           func(context.Context, *GenieGetConversationMessageRequest, ...call.Option) (*GenieMessage, error)
	messageId      string
	conversationId string
	spaceId        string
}

// Done polls once and reports whether the operation has reached a terminal state.
func (w *GenieStartConversationWaiter) Done(ctx context.Context, opts ...call.Option) (bool, error) {
	pollResp, err := w.poll(ctx, &GenieGetConversationMessageRequest{
		MessageId:      &w.messageId,
		ConversationId: &w.conversationId,
		SpaceId:        &w.spaceId,
	}, opts...)
	if err != nil {
		return false, err
	}
	if pollResp == nil {
		return false, fmt.Errorf("response is missing")
	}
	status := pollResp.Status
	if status == "" {
		return false, fmt.Errorf("response missing required status field")
	}
	switch status {
	case MessageStatus_MessageStatus_Completed, MessageStatus_MessageStatus_Failed:
		return true, nil
	default:
		return false, nil
	}
}

// Wait polls until the operation reaches a terminal state.
func (w *GenieStartConversationWaiter) Wait(ctx context.Context, opts ...lro.Option) (*GenieMessage, error) {
	var result *GenieMessage
	poll := func(ctx context.Context) error {
		pollResp, err := w.poll(ctx, &GenieGetConversationMessageRequest{
			MessageId:      &w.messageId,
			ConversationId: &w.conversationId,
			SpaceId:        &w.spaceId,
		})
		if err != nil {
			return err
		}
		if pollResp == nil {
			return fmt.Errorf("response is missing")
		}
		status := pollResp.Status
		if status == "" {
			return fmt.Errorf("response missing required status field")
		}
		switch status {
		case MessageStatus_MessageStatus_Completed:
			result = pollResp
			return nil
		case MessageStatus_MessageStatus_Failed:
			message := "(no message)"
			return fmt.Errorf("terminal state %s: %s", status, message)
		default:
			return errOperationStillRunning
		}
	}
	if err := executeWait(ctx, poll, opts...); err != nil {
		return nil, err
	}
	return result, nil
}

